import{_ as e,o as t,c as s,a3 as o}from"./chunks/framework.DdpBa4_E.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/shidai-sanbuqu/54-序.md","filePath":"books/shidai-sanbuqu/54-序.md","lastUpdated":1792645508000}'),p={name:"books/shidai-sanbuqu/54-序.md"};function r(_,a,n,i,d,c){return t(),s("div",null,[...a[0]||(a[0]=[o('<h3 id="序" tabindex="-1">序 <a class="header-anchor" href="#序" aria-label="Permalink to &quot;序&quot;">​</a></h3><p>这是我的第一部长篇小说，写完的时候，我忽然想起了《变形记》（奥维德）的最后几行：</p><p>吾诗已成。</p><p>无论大神的震怒，</p><p>还是山崩地裂，</p><p>都不能把它化为无形！</p><p>这篇粗陋的小说，当然不能和这位杰出诗人的诗篇相比。同时我想到的，还有逻辑学最基本的定理：A等于A，A不等于非A。这些话不是为我的小说而说，而是为智慧而说。在我看来，一种推理，一种关于事实的陈述，假如不是因为它本身的错误，或是相反的证据，就是对的。无论人的震怒，还是山崩地裂，无论善良还是邪恶，都不能使它有所改变。唯其如此，才能得到思维的快乐。而思维的快乐则是人生乐趣中最重要的一种。本书就是一本关于智慧，更确切地说，关于智慧的遭遇的书。</p><p>作者</p><p>1993年7月14日</p>',9)])])}const h=e(p,[["render",r]]);export{u as __pageData,h as default};
